package ru.local.jarvis;
import android.content.*;import java.io.*;import java.net.*;import javax.net.ssl.*;import java.security.*;import java.security.cert.*;import org.json.*;
final class Net{
 static String validateServer(String value)throws Exception{URI uri=new URI(value);if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||uri.getPath()!=null&&!uri.getPath().isEmpty()&&!uri.getPath().equals("/"))throw new IOException("Configure a valid HTTPS server_url");return value.endsWith("/")?value.substring(0,value.length()-1):value;}

 static void provision(Context c)throws Exception{File p=new File(c.getExternalFilesDir(null),"provision.json");if(p.exists()){byte[] b=read(new FileInputStream(p),8192);JSONObject j=new JSONObject(new String(b,"UTF-8"));c.getSharedPreferences("connection",0).edit().putString("token",j.getString("token")).putString("server_url",validateServer(j.getString("server_url"))).commit();if(!p.delete())throw new IOException("Provision cleanup failed");}}
 static byte[] read(InputStream in,int max)throws Exception{try(InputStream s=in;ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=s.read(b))!=-1){if(o.size()+n>max)throw new IOException("Response too large");o.write(b,0,n);}return o.toByteArray();}}
 static JSONObject call(Context c,String path,JSONObject body)throws Exception{String token=c.getSharedPreferences("connection",0).getString("token","");if(token.isEmpty())throw new IOException("Требуется привязка к серверу");CertificateFactory cf=CertificateFactory.getInstance("X.509");java.security.cert.Certificate cert;try(InputStream in=new FileInputStream(new File(c.getExternalFilesDir(null),"server.crt"))){cert=cf.generateCertificate(in);}KeyStore ks=KeyStore.getInstance(KeyStore.getDefaultType());ks.load(null,null);ks.setCertificateEntry("server",cert);TrustManagerFactory tm=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());tm.init(ks);SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,tm.getTrustManagers(),null);HttpsURLConnection conn=connect(c,path,ssl,token,body);try{if(body!=null){byte[] b=body.toString().getBytes("UTF-8");try(OutputStream out=conn.getOutputStream()){out.write(b);}}int code=conn.getResponseCode();if(code!=200){String detail="";try{detail=new JSONObject(new String(read(conn.getErrorStream(),2048),"UTF-8")).optString("detail");}catch(Exception ignored){}throw new IOException("Сервер "+code+": "+detail);}return new JSONObject(new String(read(conn.getInputStream(),8000000),"UTF-8"));}finally{conn.disconnect();}}
 static HttpsURLConnection connect(Context context,String path,SSLContext ssl,String token,JSONObject body)throws Exception{Exception error=null;for(String host:new String[]{validateServer(context.getSharedPreferences("connection",0).getString("server_url",""))}){HttpsURLConnection c=(HttpsURLConnection)new URL(host+path).openConnection();c.setSSLSocketFactory(ssl.getSocketFactory());c.setConnectTimeout(10000);c.setReadTimeout(path.equals("/health")?8000:110000);c.setRequestProperty("Authorization","Bearer "+token);c.setInstanceFollowRedirects(false);if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setFixedLengthStreamingMode(body.toString().getBytes("UTF-8").length);}try{c.connect();return c;}catch(Exception e){error=e;c.disconnect();}}throw error;} static String error(Exception e){if(e instanceof java.net.SocketTimeoutException)return "Сервер не ответил вовремя. Проверьте Wi-Fi/VPN.";return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
